import backtrader as bt


class APlusReversalStrategy(bt.Strategy):
    params = (
        ("aggressive_spike_allowance", 75.0),
    )

    def __init__(self):
        self.order = None
        self.stop_order = None
        self.tp1 = None
        self.tp2 = None
        self.tp3 = None

    def next(self):
        if self.order:
            return

        if self.position:
            targets = (self.tp1, self.tp2, self.tp3)
            if any(target is not None and self.data.low[0] <= target for target in targets):
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.close()
            return

        current_open = self.data.open[0]
        previous_high = self.data.high[-1]
        previous_close = self.data.close[-1]
        ict_midnight_open = current_open

        outside_day = current_open > previous_high
        gap_up = current_open > previous_close
        above_ict_midnight_open = current_open > ict_midnight_open

        if outside_day and gap_up and above_ict_midnight_open:
            self.tp1 = previous_close
            self.tp2 = previous_high
            self.tp3 = ict_midnight_open
            self.order = self.sell()

    def notify_order(self, order):
        if order.status == order.Completed:
            if order.issell() and not self.position.size == 0:
                stop_price = order.executed.price + self.p.aggressive_spike_allowance
                self.stop_order = self.buy(exectype=bt.Order.Stop, price=stop_price)
            elif order.isbuy():
                self.stop_order = None
            self.order = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.stop_order:
                self.stop_order = None
            if order is self.order:
                self.order = None
